    EStopTimer : TON;
END_VAR

EStopTimer(IN := NOT EStop, PT := T#0s);

IF EStopTimer.Q THEN
    MotorLatch := FALSE;
    Motor := FALSE;
ELSIF Start AND NOT Stop THEN
    MotorLatch := TRUE;
    Motor := MotorLatch;
ELSIF Stop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;

END_PROGRAM

