PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LastLevel : INT := 0;
    PumpTimer : TON;
END_VAR

// Check if the current level is different from the last recorded level
IF Level <> LastLevel THEN
    LastLevel := Level;

    // If the current level is at or above the high limit (90%), turn off the pump and open the valve
    IF Level >= 90 THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        // If the current level is at or below the low limit (10%), turn on the pump and close the valve
        IF Level <= 10 THEN
            PumpIn := TRUE;
            ValveOut := FALSE;
        ELSE
            // Otherwise, keep the pump and valve states as they were before
            PumpIn := FALSE;
            ValveOut := FALSE;
        END_IF;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
END_VAR
VAR_CONSTANT
    LOW_LIMIT : INT := 10;
    HIGH_LIMIT : INT := 90;
END_VAR

// Check if the level has changed significantly
IF ABS(Level - prev_Level) >= 5 THEN
    // Update previous values
    prev_Level := Level;
    prev_PumpIn := PumpIn;
    prev_ValveOut := ValveOut;

    // Determine new pump and valve states based on current level
    IF Level <= LOW_LIMIT THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= HIGH_LIMIT THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := prev_PumpIn;
        ValveOut := prev_ValveOut;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    PumpTimer : TON;
END_VAR

// Check if the level has changed significantly enough to react
IF ABS(Level - prev_Level) >= 5 THEN
    prev_Level := Level;

    // Turn off pump if level is above high limit or equal to it
    IF Level >= 90 THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        // Turn on pump if level is below low limit or equal to it
        IF Level <= 10 THEN
            PumpIn := TRUE;
            ValveOut := FALSE;
        ELSE
            // Prevent pump from running if level is above high limit
            PumpIn := FALSE;
            ValveOut := FALSE;
        END_IF;
    END_IF;
END_IF;

// Reset pump timer if pump is turned off
IF NOT PumpIn THEN
    PumpTimer(IN := FALSE);
END_IF;

// Use pump timer to ensure pump does not turn on immediately after turning off
PumpTimer(IN := PumpIn, PT := T#2s);

// Update pump output based on pump timer status
PumpIn := PumpTimer.Q;
END_PROGRAM

PROGRAM tank_level
