// Check if the level has changed significantly
IF ABS(Level - LastLevel) >= 5 THEN
    LastLevel := Level;

    // Control logic for pump and valve
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= HighLimit THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        ValveOut := FALSE;
    END_IF;

    // Safety check: never run pump when level is at or above high limit
    IF Level >= HighLimit THEN
        PumpIn := FALSE;
    END_IF;

    // Reset pump timer if pump is off
    IF NOT PumpIn THEN
        PumpTimer(IN := FALSE);
    ELSE
        PumpTimer(IN := TRUE, PT := T#10s);
    END_IF;

    // Ensure pump remains off after timer expires
    IF PumpTimer.Q AND NOT PumpIn THEN
        PumpIn := FALSE;
    END_IF;
END_IF;

END_PROGRAM

