PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT GuardClosed OR Fault, PT := T#0s);

IF StartPB AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
ELSIF StopPB OR SafetyTimer.Q THEN
    Running := FALSE;
END_IF;

Conveyor := Running;
END_PROGRAM

