PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    TNSGreen : TON;
    TNSYellow : TON;
    TNSAllRed : TON;
    TEWGreen : TON;
    TEWYellow : TON;
    TEWAllRed : TON;
END_VAR

TNSGreen(IN := State = 0 OR State = 3, PT := T#2s);
TNSYellow(IN := State = 1 OR State = 4, PT := T#1s);
TNSAllRed(IN := State = 2 OR State = 5, PT := T#1s);

TEWGreen(IN := State = 3 OR State = 0, PT := T#2s);
TEWYellow(IN := State = 4 OR State = 1, PT := T#1s);
TEWAllRed(IN := State = 5 OR State = 2, PT := T#1s);

NS_G := TNSGreen.Q AND NOT TNSYellow.Q AND NOT TNSAllRed.Q;
NS_Y := TNSYellow.Q AND NOT TNSGreen.Q AND NOT TNSAllRed.Q;
NS_R := TNSAllRed.Q OR (TNSGreen.Q AND TNSYellow.Q);

EW_G := TEWGreen.Q AND NOT TEWYellow.Q AND NOT TEWAllRed.Q;
EW_Y := TEWYellow.Q AND NOT TEWGreen.Q AND NOT TEWAllRed.Q;
EW_R := TEWAllRed.Q OR (TEWGreen.Q AND TEWYellow.Q);

CASE State OF
    0: State := 1;
    1: State := 2;
    2: State := 3;
    3: State := 4;
    4: State := 5;
    5: State := 0;
END_CASE;

END_PROGRAM

