        TAllRed(IN := FALSE, PT := T#0s);
        TGreen_EW(IN := TRUE, PT := PT_GREEN);
        TYellow_EW(IN := FALSE, PT := T#0s);

    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        TGreen_NS(IN := FALSE, PT := T#0s);
        TYellow_NS(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
        TGreen_EW(IN := FALSE, PT := T#0s);
