ELSIF TGreen_EW.Q THEN
    State := 4;
ELSIF TYellow_EW.Q THEN
    State := 5;
END_IF;

NS_G := NOT(TGreen_EW.Q OR TYellow_EW.Q);
NS_Y := TYellow_EW.Q;
NS_R := TAllRed.Q OR TGreen_EW.Q;

EW_G := NOT(TGreen_NS.Q OR TYellow_NS.Q);
