    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
    EntryTimer : TON;
END_VAR

// Edge detection for EntrySensor
PrevEntry := EntrySensor;

IF NOT PrevEntry AND EntrySensor THEN
    // Rising edge detected
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

// Edge detection for ExitSensor
PrevExit := ExitSensor;

IF Not PrevExit AND ExitSensor THEN
    // Rising edge detected
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

// Determine if the garage is full
FullSign := Count = CAP;

// Control the entry barrier
EntryBarrierOpen := EntryReq AND NOT FullSign;

END_PROGRAM

