PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    StartTimer : TON;
    MotorOn : BOOL;
END_VAR

// Initialize motor state to off
Motor := FALSE;

// Check for emergency stop
IF NOT EStop THEN
    // Reset motor state and stop timer if emergency stop is active
    Motor := FALSE;
    StartTimer(IN := FALSE);
    MotorOn := FALSE;
END_IF;

// If emergency stop is not active, check start command
IF EStop THEN
    // Check if start command has been held for the required delay
    IF StartCmd AND NOT MotorOn THEN
        StartTimer(IN := TRUE, PT := T#3s);
        IF StartTimer.Q THEN
            Motor := TRUE;
            MotorOn := TRUE;
        END_IF;
    ELSE
        // If start command is released or held too briefly, reset motor state
        IF NOT StartCmd OR MotorOn THEN
            Motor := FALSE;
            MotorOn := FALSE;
            StartTimer(IN := FALSE);
        END_IF;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    StartTimer : TON;
    MotorStarted : BOOL := FALSE;
END_VAR

StartTimer(IN := StartCmd AND NOT EStop, PT := T#3s);

IF EStop THEN
    Motor := FALSE;
    MotorStarted := FALSE;
ELSIF StartTimer.Q AND NOT MotorStarted THEN
    Motor := TRUE;
    MotorStarted := TRUE;
ELSIF NOT StartCmd THEN
    Motor := FALSE;
    MotorStarted := FALSE;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    StartTimer : TON;
    MotorEnabled : BOOL := FALSE;
END_VAR

// Reset the motor enabled flag if emergency stop is activated
IF NOT EStop THEN
    MotorEnabled := FALSE;
END_IF;

// If not already running and start command is held for the required delay
IF NOT MotorEnabled AND StartCmd AND NOT EStop THEN
    StartTimer(IN := TRUE, PT := T#3s);
END_IF;

// Check if the timer has elapsed and update the motor state accordingly
IF StartTimer.Q AND StartCmd AND NOT EStop THEN
    MotorEnabled := TRUE;
    Motor := TRUE;
END_IF;

// Stop the motor and reset the timer if start command is released or emergency stop is activated
IF NOT StartCmd OR NOT EStop THEN
    MotorEnabled := FALSE;
    Motor := FALSE;
    StartTimer(IN := FALSE);
END_IF;
END_PROGRAM

