END_VAR
VAR
    StartTimer : TON;
    MotorStarted : BOOL := FALSE;
END_VAR

// Reset motor state if EStop is active
IF NOT EStop THEN
    Motor := FALSE;
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
END_IF;

// If EStop is not active and StartCmd is maintained for the delay time
IF EStop AND StartCmd THEN
    StartTimer(IN := TRUE, PT := T#3s);
    IF StartTimer.Q THEN
        Motor := TRUE;
        MotorStarted := TRUE;
    END_IF;
END_IF;

// Release motor if StartCmd is released before the delay is complete
IF NOT StartCmd AND MotorStarted THEN
    Motor := FALSE;
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    HoldCount : INT := 0;
    MaxHoldTicks : INT := 3;
END_VAR

Motor := FALSE;

IF NOT EStop THEN
    IF StartCmd AND NOT StartTimer.Q THEN
        StartTimer(IN := TRUE, PT := T#1ms);
    END_IF;

    IF StartTimer.Q THEN
        HoldCount := HoldCount + 1;
        IF HoldCount >= MaxHoldTicks THEN
            Motor := TRUE;
        END_IF;
    ELSE
        HoldCount := 0;
    END_IF;

    IF NOT StartCmd OR EStop THEN
        Motor := FALSE;
        StartTimer(IN := FALSE);
        HoldCount := 0;
    END_IF;
END_IF;

END_PROGRAM

