    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR

VAR
    State : INT := 0;
    PT_STAR : TIME := T#3s;
    StarTimer : TON;
END_VAR

StarTimer(IN := NOT EStop AND StartPB AND State = 0, PT := PT_STAR);

CASE State OF
    0: // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF NOT EStop AND StartPB THEN
            State := 1;
        END_IF;

    1: // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF StarTimer.Q THEN
            State := 2;
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
    MainK := FALSE;
    StarK := FALSE;
    DeltaK := FALSE;
END_IF;
END_PROGRAM

