    PrevDemand : BOOL := FALSE;
    T_EStop : TON;
END_VAR

T_EStop(IN := NOT EStop, PT := T#1s);

Pump1 := FALSE;
Pump2 := FALSE;

IF T_EStop.Q THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    PrevDemand := Demand;

    IF Demand THEN
        IF Lead = 0 THEN
            Pump1 := TRUE;
        ELSE
            Pump2 := TRUE;
        END_IF;
    END_IF;
END_IF;

