IF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead; // Toggle lead
END_IF;

// Assign pumps based on lead
CASE Lead OF
    0: 
        Pump1 := Demand;
        Pump2 := FALSE;
    1: 
        Pump1 := FALSE;
        Pump2 := Demand;
END_CASE;

